"use client";
/* Lurk, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Lurk(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("lurk"); }, []);
  return React.createElement("piix-pal", { "pal": "lurk", ...piixAttrs(props) });
}

export default Lurk;
